WFJ.Data.add("book", {
  ["49106544308ab1b1"] = { "Mentre i Titani attraversavano il paesaggio primordiale, incontrarono numerosi esseri elementali ostili. Questi elementali, che adoravano una razza di esseri di insondabile malvagità noti solo come Dei Antichi, giurarono di respingere i Titani e di preservare il loro mondo dal tocco metallico degli invasori.", "." },
  ["49191231f6d23764"] = { "Ma prima di liquidare tali racconti, sia chiaro al lettore: i worgen esistono. Forse non provengono dal nostro mondo, ma esistono vie tra la loro dimora e la nostra, e potenti magie possono trascinarli qui.\n\nÈ meglio non pronunciare mai simili formule, perché ovunque passino i worgen portano con sé terrore e spargimento di sangue.", "." },
  ["498ead97e6e6ee54"] = { "Le ⟦Green Hills of Stranglethorn=Verdi Colline di Rovotorto⟧\n\nIl nostro primo giorno è andato bene quanto ci si può aspettare da un primo giorno. Gran parte del tempo l'abbiamo dedicata ai preparativi necessari per allestire un campo base. Ho trovato un luogo ideale presso un'insenatura di un fiume d'acqua dolce. A giudicare dai vecchi moli abbandonati lì vicino, il posto era stato abitato tempo addietro. Quanto ai suoi primi abitanti, solo il tempo potrà raccontarne la storia.", "." },
  ["499a55551b5a6174"] = { "Mentre Thrall liberava i suoi fratelli a Lordaeron, Ner'zhul continuava a consolidare il proprio potere in Nordania. Una grande cittadella fu eretta sopra il ghiacciaio della Corona di Ghiaccio e presidiata dalle legioni sempre più numerose dei morti. Eppure, mentre il Re dei Lich estendeva la sua influenza su quella terra, un oscuro impero si oppose al suo potere.", "." },
  ["49dbaed5e1710ecc"] = { "Dopo che i Lupi Bianchi esiliati ebbero varcato il portale, solo pochi clan di orchi li seguirono. Questi orchi stabilirono rapidamente una base operativa nella Palude Nera, una zona oscura e paludosa molto a est del regno di ⟦Stormwind=Roccavento⟧. Quando gli orchi cominciarono a spingersi oltre e a esplorare le nuove terre, entrarono subito in conflitto con i difensori umani di ⟦Stormwind=Roccavento⟧.", "." },
})
